from alembic import command
from alembic.config import Config
from sqlalchemy import Engine, inspect

from app.db.base import Base


def test_migrations_create_every_model_table(migrated_engine: Engine) -> None:
    tables = set(inspect(migrated_engine).get_table_names())

    assert set(Base.metadata.tables) <= tables


def test_models_and_migrations_are_in_sync(migrated_engine: Engine, alembic_cfg: Config) -> None:
    # Raises AutogenerateDiffsDetected if a model changed without a migration.
    command.check(alembic_cfg)


def test_downgrade_to_base_and_back_up(migrated_engine: Engine, alembic_cfg: Config) -> None:
    command.downgrade(alembic_cfg, "base")
    assert set(inspect(migrated_engine).get_table_names()) == {"alembic_version"}

    command.upgrade(alembic_cfg, "head")
    assert set(Base.metadata.tables) <= set(inspect(migrated_engine).get_table_names())
